solution:
use xiom.io;

use xiom.string;
type NonEmptyStr = {
  value: Str;
  invariant: string.str_len(value) > 0;
}

fn NonEmptyStr.new(s: Str) -> Option[NonEmptyStr] {
  if string.str_len(s) == 0 { return None; }
  return Some(NonEmptyStr{ value: s });
}

fn NonEmptyStr.capitalize(self) -> NonEmptyStr {
  let first = self.value[0];
  let rest = string.str_slice(self.value, 1, string.str_len(self.value));
  let uppered = string.str_upper(string.char_to_str(first));
  return NonEmptyStr{ value: uppered + rest };
}

fn main() -> Int {
  let name = NonEmptyStr.new("kilo");
  match name {
    Some(n) => {
      let capped = n.capitalize();
      io.println("Hello, " + capped.value.to_str() + "!");
    };
    None => { io.println("Error: empty name"); };
  }
  return 0;
}
